/// Licence attached to a project. agreed_at pairs with agreed_by_user_id under a check constraint; pending exactly when agreed_at is null.
#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
pub struct ProjectLicense {
    /// Project.
    pub project_id: uuid::Uuid,
    /// Licence.
    pub licence_id: String,
    /// Agreement timestamp; null while pending.
    pub agreed_at: Option<chrono::DateTime<chrono::Utc>>,
    /// Agreeing user; null together with agreed_at.
    pub agreed_by_user_id: Option<uuid::Uuid>,
}

// ── platform: Platform entities backing the corpora apps (Postgres tables). ──

/// One commit from the corpus' nested .git, newest first.
#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
pub struct CorpusCommit {
    /// Commit record identity.
    pub id: uuid::Uuid,
    /// Parent corpus document.
    pub document_id: uuid::Uuid,
    /// Commit SHA.
    pub sha: String,
    /// Commit message.
    pub message: String,
    /// Author name.
    pub author_name: Option<String>,
    /// Author email.
    pub author_email: Option<String>,
    /// Branch name.
    pub branch: Option<String>,
    /// Commit timestamp.
    pub committed_at: Option<chrono::DateTime<chrono::Utc>>,
}

/// Corpus archive imported into a project, with conversion metadata from the corpora-py contract.
#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
pub struct CorpusDocument {
    /// Record identity.
    pub id: uuid::Uuid,
    /// Owning project.
    pub project_id: uuid::Uuid,
    /// Corpus name.
    pub name: String,
    /// Origin: upload or huggingface.
    pub source: CorpusSource,
    /// Storage path for uploads, the full URL for Hugging Face.
    pub path: String,
    /// Original filename.
    pub filename: Option<String>,
    /// Conversion job id for explore routes; null on uploads.
    pub job_id: Option<String>,
    /// Upload time.
    pub uploaded_at: chrono::DateTime<chrono::Utc>,
    /// Manifest type; null on legacy rows.
    pub corpus_type: Option<CorpusType>,
    /// source_format as sent to POST /convert (text-fabric, tei, ...).
    pub source_format: Option<String>,
    /// Licence from the manifest.
    pub licence: Option<String>,
    /// Language from the manifest.
    pub language: Option<String>,
    /// Archive size in bytes.
    pub size_bytes: Option<i64>,
    /// Document count.
    pub docs_count: Option<i64>,
    /// Total node count.
    pub nodes: Option<i64>,
    /// Total word count.
    pub words: Option<i64>,
    /// Processing status.
    pub status: Option<DocumentStatus>,
    /// Conversion completion time.
    pub converted_at: Option<chrono::DateTime<chrono::Utc>>,
    /// Manifest description, captured at conversion time.
    pub description: Option<String>,
    /// toc.yml section rows captured at conversion time.
    pub toc: Option<Vec<CorpusTocSection>>,
}

/// Published corpus in the library catalog.
#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
pub struct LibraryCorpus {
    /// Unique corpus identifier.
    pub uid: String,
    /// Display name.
    pub name: String,
    /// Primary language.
    pub language: Option<String>,
    /// Corpus type.
    #[serde(rename = "type")]
    pub r#type: Option<String>,
    /// Content category.
    pub category: Option<String>,
    /// Corpus version.
    pub version: String,
    /// Availability flag.
    pub available: bool,
}

/// Organization or institution owning projects.
#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
pub struct Organization {
    /// Organization identity.
    pub id: uuid::Uuid,
    /// Organization name.
    pub name: String,
    /// Organization website.
    pub website: Option<String>,
    /// Creation time.
    pub created_at: chrono::DateTime<chrono::Utc>,
}

/// A scholarly project; scriptural types require languages (FR-006), categorized types require a category (FR-007).
#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
pub struct Project {
    /// Project identity.
    pub id: uuid::Uuid,
    /// Project name.
    pub name: String,
    /// Project description.
    pub description: Option<String>,
    /// Workflow status.
    pub status: ProjectStatus,
    /// Work classification.
    #[serde(rename = "type")]
    pub r#type: Option<BookType>,
    /// Source languages for scriptural types; empty when not applicable.
    pub language: Option<Vec<LanguageType>>,
    /// Content category for categorized types.
    pub category: Option<CategoryType>,
    /// Creating user; never null (FR-015).
    pub creator_id: uuid::Uuid,
    /// Owning organization.
    pub organization_id: Option<uuid::Uuid>,
    /// Creation time.
    pub created_at: chrono::DateTime<chrono::Utc>,
    /// Last update time.
    pub updated_at: chrono::DateTime<chrono::Utc>,
}

/// Library corpora loaded alongside a project's dataset.
#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
pub struct ProjectCorpusLink {
    /// Project.
    pub project_id: uuid::Uuid,
    /// Library corpus.
    pub corpus_id: String,
    /// Link creation time.
    pub linked_at: chrono::DateTime<chrono::Utc>,
}

/// Directory user with profile fields.
#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
pub struct User {
    /// User identity.
    pub id: uuid::Uuid,
    /// Handle used in mentions and links, without the @.
    pub username: String,
    /// Email address.
    pub email: String,
    /// Full name, shown across Corpora.
    pub name: Option<String>,
    /// Portrait image URL; the UI falls back to initials.
    pub avatar_url: Option<String>,
    /// One of VOCATIONS, or a value written before the list existed.
    pub vocation: Option<String>,
    /// One of TRADITIONS, or a value written before the list existed.
    pub tradition: Option<String>,
    /// Working languages, freeform.
    pub languages: Option<String>,
    /// Institution or society.
    pub affiliation: Option<String>,
    /// Personal or academic site, without the scheme.
    pub website: Option<String>,
    /// Short profile summary.
    pub bio: Option<String>,
    /// Account creation time.
    pub created_at: chrono::DateTime<chrono::Utc>,
    /// Last profile update.
    pub updated_at: Option<chrono::DateTime<chrono::Utc>>,
}
